import type { WelcomeCapability } from './interfaces';
import { inferCliProviderKey } from '../shared/providerConstants';

/** What a new chat talks to: an agent in a folder on the Mac, a shell there, or a model with no folder. */
export type ChatStarterKind = 'coding' | 'shell' | 'assistant';

/** A further list a row opens instead of filling the composer: ideas to choose between. */
export interface StarterIdeas {
  title: string;
  /** The words at the end of `title` set in italic. */
  emphasis: string;
  rows: WelcomeCapability[];
}

/** A starter row. With `more`, a tap opens that list; without, it fills the composer with `example`. */
export interface StarterCapability extends WelcomeCapability {
  more?: StarterIdeas;
}

export interface ChatStarters {
  /** What the chat talks to, in a few words, shown small above the heading. */
  eyebrow: string;
  title: string;
  /** The words at the end of `title` the first-party screen sets in italic. */
  emphasis: string;
  rows: StarterCapability[];
}

/**
 * `provider` is the CLI the chat has already run on, when known; it outranks
 * `modelId`, the model picked for the next turn.
 */
export function chatStarterKind(modelId: string | null | undefined, provider?: string | null): ChatStarterKind {
  const key = provider ?? inferCliProviderKey(modelId);
  if (!key) return 'assistant';
  return key === 'shell-cli' ? 'shell' : 'coding';
}

// Things to make, offered by every chat that has an agent behind it. Each opens
// a list of ideas; the last idea in each is open-ended, for the reader's own.
const EXTENSION_IDEAS: StarterCapability = {
  icon: 'fa-puzzle-piece', title: 'Build a browser extension',
  description: 'Change a website you use so it works better for you',
  example: 'Build a browser extension artefact. Ask me which site it is for and what it should change.',
  more: {
    title: 'Which site shall we improve?', emphasis: 'improve?',
    rows: [{
      icon: 'fa-utensils', title: 'Recipes without the story',
      description: 'Ingredients and method at the top of the page',
      example: 'Build a browser extension artefact for recipe sites. Move the ingredients and the method to the top of the page and hide everything that comes before them.',
    }, {
      icon: 'fa-tag', title: 'Prices you can compare',
      description: 'The price per unit beside every price',
      example: 'Build a browser extension artefact for shopping sites. Beside each price, show the price per unit (per 100 g, per litre or per item) so I can compare like with like.',
    }, {
      icon: 'fa-clock', title: 'Times in my time zone',
      description: 'Every time on a page, rewritten for where I am',
      example: 'Build a browser extension artefact that rewrites every time and date on a page into my own time zone, and shows the original when I hover over it.',
    }, {
      icon: 'fa-book-open', title: 'Easier reading',
      description: 'A comfortable column, larger type, no clutter',
      example: 'Build a browser extension artefact for articles. Give the text a comfortable width, larger type and more space between lines, and hide the sidebars and banners.',
    }, {
      icon: 'fa-list', title: 'A contents list for long pages',
      description: 'Jump straight to the part you want',
      example: 'Build a browser extension artefact that adds a contents list to long pages, built from their headings, so I can jump to any section.',
    }, {
      icon: 'fa-pen', title: 'Something of my own',
      description: 'Name a site and say what annoys you about it',
      example: 'Build a browser extension artefact for this site: \n\nWhat I want it to change: ',
    }],
  },
};

const ARTEFACT_IDEAS: StarterCapability = {
  icon: 'fa-wand-magic-sparkles', title: 'Build a Ripul artefact',
  description: 'A small tool or page to keep, use and share',
  example: 'Make me an artefact. Ask me what it is for, then build it.',
  more: {
    title: 'What would be useful?', emphasis: 'be useful?',
    rows: [{
      icon: 'fa-chart-column', title: 'A chart of GitHub commits',
      description: 'Who committed what, person by person, day by day',
      example: 'Make me an artefact: a chart of GitHub commits by person by day. Use this repository if we are in one, otherwise ask me which. Stack each day by person, and let me choose how far back it goes.',
    }, {
      icon: 'fa-calculator', title: 'A calculator',
      description: 'Quotes, tips, margins: the sum you keep doing by hand',
      example: 'Make me an artefact: a calculator. Ask me what it should work out and what goes in, then build it so it works well on my phone.',
    }, {
      icon: 'fa-calendar-week', title: 'A planner',
      description: 'The week ahead, with things to tick off',
      example: 'Make me an artefact: a planner for the week ahead, with tasks I can add and tick off, that works well on my phone.',
    }, {
      icon: 'fa-list-check', title: 'A checklist',
      description: 'A routine you want done the same way every time',
      example: 'Make me an artefact: a checklist for a routine I repeat. Ask me the steps, then build it so I can tick them off and start again.',
    }, {
      icon: 'fa-people-group', title: 'Something for my team',
      description: 'A small tool you can share with the people who need it',
      example: 'Make me an artefact my team can use. Ask me what it is for and who will use it, then build it.',
    }, {
      icon: 'fa-pen', title: 'Something of my own',
      description: 'Describe it in a sentence',
      example: 'Make me an artefact: ',
    }],
  },
};

// Only for a chat with a project behind it: the files Ripul's own tools read from a repository.
const PROJECT_SETUP_IDEAS: StarterCapability = {
  icon: 'fa-screwdriver-wrench', title: 'Set this project up for Ripul',
  description: 'The few files that make our tools work well here',
  example: 'Look at how this project is set up for working with Ripul and tell me what is missing: Trainyard tracks in .ripul/trains.yaml, instructions for agents, and a way to build and run it. Change nothing yet.',
  more: {
    title: 'What shall we set up?', emphasis: 'set up?',
    rows: [{
      icon: 'fa-train', title: 'Trainyard, for builds and deploys',
      description: 'A track for each job, so several agents can ship in turn',
      example: 'Set this project up for Trainyard. Work out how it is built and deployed, then write .ripul/trains.yaml with a track for each job and the resources those jobs disturb. Show me the file before you commit it, and check it with `ripul-train config`.',
    }, {
      icon: 'fa-file-lines', title: 'Instructions for every agent',
      description: 'How this project is built, tested and committed, written down once',
      example: 'Write the instructions agents should follow in this project: how it is laid out, how to build and test it, and the rules for commits. Put them in CLAUDE.md and point AGENTS.md at it, so every agent reads the same thing. Show me before you commit.',
    }, {
      icon: 'fa-mobile-screen', title: 'Run on my iPhone',
      description: 'Find how this builds for a phone and make it one step',
      example: 'Work out how this project builds and runs on an iPhone, try it on mine, and write down the steps so any agent can do it again.',
    }, {
      icon: 'fa-magnifying-glass', title: 'Check what is missing',
      description: 'A look over the project, changing nothing',
      example: 'Look at how this project is set up for working with Ripul and tell me what is missing: Trainyard tracks in .ripul/trains.yaml, instructions for agents, and a way to build and run it. Change nothing yet.',
    }],
  },
};

// The rows an empty chat opens with. A tap fills the composer and does not
// send, so `example` is read and edited before anything runs on the Mac. Shell
// examples are the command itself: a Shell chat runs its message as typed.
export const CHAT_STARTERS: Readonly<Record<ChatStarterKind, ChatStarters>> = {
  coding: {
    eyebrow: 'Coding agent', title: 'What shall we work on?', emphasis: 'work on?',
    rows: [{
      icon: 'fa-folder-open', title: 'Explain this project',
      description: 'What it does and how it is laid out',
      example: 'Look through this folder and explain what the project does and how it is laid out.',
    }, {
      icon: 'fa-code-branch', title: 'Review my changes',
      description: 'A second look at what is not committed yet',
      example: 'Review my uncommitted changes and tell me about anything that looks wrong.',
    }, {
      icon: 'fa-clock-rotate-left', title: 'What changed lately',
      description: 'The last week of commits, in plain words',
      example: 'Summarise what changed in this repository over the last week.',
    }, {
      icon: 'fa-mobile-screen', title: 'Run it on my iPhone',
      description: 'Build this project and open it on the phone',
      example: 'Build this project and run it on my iPhone.',
    }, PROJECT_SETUP_IDEAS, EXTENSION_IDEAS, ARTEFACT_IDEAS],
  },
  shell: {
    eyebrow: 'Shell on your Mac', title: 'Run a command on your Mac', emphasis: 'on your Mac',
    rows: [{
      icon: 'fa-folder-open', title: 'See where you are',
      description: 'The folder this shell is in, and what is in it',
      example: 'pwd && ls',
    }, {
      icon: 'fa-code-branch', title: 'Check the repository',
      description: 'The branch and what is not committed',
      example: 'git status',
    }, {
      icon: 'fa-clock-rotate-left', title: 'Recent commits',
      description: 'The last ten, one line each',
      example: 'git log --oneline -10',
    }],
  },
  assistant: {
    eyebrow: 'Assistant', title: 'What can I help you with?', emphasis: 'help you with?',
    rows: [EXTENSION_IDEAS, ARTEFACT_IDEAS, {
      icon: 'fa-list-check', title: 'Plan a piece of work',
      description: 'The steps, the risks and what to do first',
      example: 'Help me plan a piece of work. Ask me what it is, then break it into steps.',
    }, {
      icon: 'fa-align-left', title: 'Summarise something',
      description: 'Paste text and get the short version',
      example: 'Summarise this for me:\n\n',
    }],
  },
};

