import { AgentContext } from '../../agent/AgentContext';
import { ToolDefinition } from '../Tools';

/**
 * ripul_guide: what an agent needs to know to use Ripul, a topic at a time.
 *
 * The guides are plain Markdown in public/guides/, listed by index.json and
 * served beside the app, so they go live with a deploy and every agent the
 * harness runs (Claude, Codex, Antigravity, the web and phone chats) reads the
 * same text. Nothing is cached across calls: a guide is a few kilobytes and a
 * stale one is worse than a second fetch.
 */

interface GuideEntry {
  id: string;
  title: string;
  when: string;
}

const GUIDES_PATH = '/guides';

async function fetchText(path: string): Promise<string> {
  const response = await fetch(path, { cache: 'no-store' });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const text = await response.text();
  // Pages answers an unknown path with the app's HTML shell and a 200.
  if (/^\s*<!doctype html|^\s*<html/i.test(text)) throw new Error('not found');
  return text;
}

async function loadIndex(): Promise<GuideEntry[]> {
  const parsed = JSON.parse(await fetchText(`${GUIDES_PATH}/index.json`));
  return Array.isArray(parsed?.guides) ? parsed.guides : [];
}

export async function ripulGuideHandler(
  _context: AgentContext,
  _tool: ToolDefinition,
  params: any
): Promise<any> {
  const topic = typeof params?.topic === 'string' ? params.topic.trim().toLowerCase() : '';

  let guides: GuideEntry[];
  try {
    guides = await loadIndex();
  } catch (error) {
    return { error: `The Ripul guides could not be loaded (${error instanceof Error ? error.message : error}).` };
  }

  if (!topic) {
    return {
      guides,
      next: 'Call ripul_guide again with one of these ids as `topic` to read that guide.',
    };
  }

  const entry = guides.find((guide) => guide.id === topic);
  if (!entry) {
    return { error: `There is no guide called '${topic}'.`, guides };
  }

  try {
    return { topic: entry.id, title: entry.title, guide: await fetchText(`${GUIDES_PATH}/${entry.id}.md`) };
  } catch (error) {
    return { error: `The '${entry.id}' guide could not be loaded (${error instanceof Error ? error.message : error}).`, guides };
  }
}
