describe('an empty chat in the Ripul app', () => {
  // The app boots through a site key, which on its own means "no built-in rows".
  const app = () => { state.features = { ...RIPUL_IPHONE_PRESENTATION }; state.siteKeyConfig = true; };

  it('opens with rows for a coding agent', () => {
    app();
    state.descriptors = chat('claude-cli-raw-sonnet');
    const html = render();
    expect(words(html)).toContain(CHAT_STARTERS.coding.title);
    expect(words(html)).toContain(CHAT_STARTERS.coding.eyebrow);
    for (const row of CHAT_STARTERS.coding.rows) expect(html).toContain(row.title);
    expect(html).toContain('V2WelcomeScreen.capabilityRow');
    expect(html).not.toContain('No messages yet');
  });

  it('offers a Shell chat commands, and a plain model its own rows', () => {
    app();
    state.descriptors = chat('shell-cli-raw-default');
    expect(render()).toContain('Check the repository');
    state.descriptors = chat('gpt-5');
    expect(render()).toContain('Build a Ripul artefact');
  });

  it('offers things to make, each opening ideas of its own', () => {
    app();
    for (const model of ['claude-cli-raw-sonnet', 'gpt-5']) {
      state.descriptors = chat(model);
      const html = render();
      expect(html).toContain('Build a browser extension');
      expect(html).toContain('Build a Ripul artefact');
      // Both say they lead somewhere, and their ideas stay shut until asked for.
      // A coding chat has a project behind it, so it also offers to set that up.
      expect(html.split('V2StarterScreen.row.more').length - 1).toBe(model === 'gpt-5' ? 2 : 3);
      expect(html.includes('Set this project up for Ripul')).toBe(model !== 'gpt-5');
      expect(html).not.toContain('Recipes without the story');
    }
    // A shell runs commands; it has nobody to build with.
    state.descriptors = chat('shell-cli-raw-default');
    expect(render()).not.toContain('Build a browser extension');
  });

  it('gives every idea words for the composer and a heading that ends in its italic', () => {
    const lists = [...CHAT_STARTERS.coding.rows, ...CHAT_STARTERS.assistant.rows].flatMap((row) => (row.more ? [row.more] : []));
    expect(lists.length).toBe(5);
    for (const list of lists) {
      expect(list.title.endsWith(list.emphasis)).toBe(true);
      for (const idea of list.rows) expect(idea.example.length).toBeGreaterThan(10);
    }
  });
