open(p,'w').write(s)
EOF
cat > chrome-extension/scripts/sync-theming-guide.mjs <<'EOF'
#!/usr/bin/env node
// The `theming` guide and the SDK's "theme an app" skill are one text.
//
// The source is ripul-ios-sdk/tools/skills/theme-an-app/SKILL.md, which ships in the
// public package for an agent that is not inside Ripul. The guide that ripul_guide
// serves, public/guides/theming.md, is that file without its front matter, byte for
// byte. Edit the skill, then run this.
//
//   node scripts/sync-theming-guide.mjs           write the guide from the skill
//   node scripts/sync-theming-guide.mjs --check   exit 1 if they differ (the build runs this)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const skillPath = resolve(root, '../ripul-ios-sdk/tools/skills/theme-an-app/SKILL.md');
const guidePath = resolve(root, 'public/guides/theming.md');

/** The skill without its front matter: what an agent inside Ripul reads as the guide. */
export function guideFromSkill(skill) {
  const match = /^---\n[\s\S]*?\n---\n+/.exec(skill);
  if (!match) throw new Error(`${skillPath} has no front matter`);
  return skill.slice(match[0].length);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const wanted = guideFromSkill(readFileSync(skillPath, 'utf8'));
  if (process.argv.includes('--check')) {
    let current = '';
    try { current = readFileSync(guidePath, 'utf8'); } catch { /* missing counts as different */ }
    if (current !== wanted) {
      console.error('public/guides/theming.md is not the SDK skill it is made from.');
      console.error('Edit ripul-ios-sdk/tools/skills/theme-an-app/SKILL.md, then run: node scripts/sync-theming-guide.mjs');
      process.exit(1);
    }
  } else {
    writeFileSync(guidePath, wanted);
    console.log(`wrote ${guidePath}`);
  }
}
EOF
